            other_colors = colors - {color}
            if len(other_colors) == 1:
                foreground = color
                break

    # If we found foreground, transform it to 2
    if foreground is not None:
        result = [[2 if cell == foreground else cell for cell in row] for row in grid]
    else:
        # Fallback: try to determine by finding the most common non-background color
        result = grid

    return result
